"""Verify every bounds rejection the parser reports is a genuine bound breach."""
import random, sys
sys.path[:0] = ['/workspace/project', '/opt/emicro-deps']
import syntax
from lark import Lark, Tree

GRAMMAR = open('/workspace/tmp/dev/larkdiff.py').read().split("GRAMMAR = r'''")[1].split("'''")[0]
lark_parser = Lark(GRAMMAR, parser='lalr', maybe_placeholders=False)

ATOMS = ('match', 'startswith', 'endswith', 'contains')


def to_rules(tree):
    out = []
    for policy in tree.children:
        predicate, action = policy.children[0], policy.children[1]
        out.append((convert(predicate), str(action) == 'allow'))
    return out


def convert(node):
    if isinstance(node, str):
        return ('match', (node,)) if False else node
    data = node.data
    if data in ATOMS:
        path = tuple(str(child) for child in node.children[0].children)
        return (data, path)
    if data == 'not_':
        return ('not', convert(node.children[0]))
    return (data, convert(node.children[0]), convert(node.children[1]))


def census(rules):
    atoms = symbols = 0
    depth = 0
    complex_rules = 0
    nonliteral = set()
    per_complex = 0
    for predicate, _ in rules:
        stack = [(predicate, 1)]
        local = 0
        while stack:
            node, level = stack.pop()
            depth = max(depth, level)
            kind = node[0]
            if kind in ATOMS:
                atoms += 1
                local += 1
                symbols += len(node[1])
                if kind != 'match':
                    nonliteral.add(node)
            elif kind == 'not':
                stack.append((node[1], level + 1))
            else:
                stack.append((node[1], level + 1))
                stack.append((node[2], level + 1))
        if predicate[0] != 'match':
            complex_rules += 1
            per_complex = max(per_complex, local)
    return {'atoms': atoms, 'symbols': symbols, 'depth': depth,
            'complex_rules': complex_rules, 'per_complex_atoms': per_complex,
            'nonliteral': len(nonliteral)}


def breaches(facts):
    out = []
    if facts['depth'] > 16: out.append('predicate depth')
    if facts['atoms'] > 32768: out.append('occurrence budget')
    if facts['symbols'] > 65536: out.append('occurrence budget')
    if facts['complex_rules'] > 8: out.append('complex rule count')
    if facts['per_complex_atoms'] > 32: out.append('complex rule atoms')
    if facts['nonliteral'] > 4: out.append('distinct nonliteral atoms')
    if any(len(node[1]) > 16 for node in []): pass
    return out


def main(rounds=40000, seed=99):
    rng = random.Random(seed)
    sys.path.insert(0, '/workspace/tmp/dev')
    import larkdiff
    problems = 0
    checked_bounds = 0
    for _ in range(rounds):
        if rng.random() < .55:
            text = ''.join(larkdiff.mutate(larkdiff.skeleton(rng), rng))
        else:
            text = ''.join(rng.choice(larkdiff.PIECES) for _ in range(rng.randint(0, 14)))
        try:
            tree = lark_parser.parse(text)
        except Exception:
            continue
        try:
            syntax.parse(text)
            continue
        except syntax.PolicyError as exc:
            message = str(exc)
            if message not in ('predicate depth', 'path length', 'nonliteral path length',
                               'complex rule count', 'complex rule atoms', 'occurrence budget',
                               'distinct nonliteral atoms', 'token budget'):
                print('SYNTAX DIFFERENCE (lark accepted):', repr(text), message)
                problems += 1
                continue
        facts = census(to_rules(tree))
        # path length bounds are lexical, recompute directly
        long_path = False
        stack = [p for p, _ in to_rules(tree)]
        while stack:
            node = stack.pop()
            if node[0] in ATOMS:
                if len(node[1]) > 16: long_path = True
                if node[0] != 'match' and len(node[1]) > 4: long_path = True
            elif node[0] == 'not':
                stack.append(node[1])
            else:
                stack.extend((node[1], node[2]))
        reasons = breaches(facts)
        if long_path:
            reasons.append('path length')
        if not reasons:
            print('FALSE BOUND REJECTION:', repr(text), facts)
            problems += 1
        checked_bounds += 1
    print('bound audit rounds=%d audited=%d problems=%d' % (rounds, checked_bounds, problems))


if __name__ == '__main__':
    main(int(sys.argv[1]) if len(sys.argv) > 1 else 40000, int(sys.argv[2]) if len(sys.argv) > 2 else 99)
